templateJson.css:
@page { margin: 0; }
* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  background: var(--color-page);
  color: var(--color-text);
  font-family: var(--font-sans), sans-serif;
  font-size: 11pt;
  line-height: 1.55;
}
.page-frame {
  padding: 30pt 34pt 76pt;
}
.cover {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 42pt 40pt;
  background: var(--color-primary);
  color: #ffffff;
  page-break-after: always;
  break-after: page;
}
.cover .cover-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16pt;
}
.cover .logo img {
  max-height: 34pt;
  max-width: 160pt;
  display: block;
}
.cover .kicker {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 9.5pt;
  color: var(--color-gold);
  font-weight: 700;
}
.cover .cover-heading h1 {
  font-family: var(--font-heading), serif;
  font-size: 32pt;
  line-height: 1.15;
  margin: 14pt 0 10pt;
}
.cover .deck {
  font-size: 13.5pt;
  max-width: 34em;
  color: rgba(255, 255, 255, 0.88);
  margin: 0 0 10pt;
}
.cover .byline {
  font-size: 9.5pt;
  color: rgba(255, 255, 255, 0.7);
}
.cover .cover-image {
  margin-top: 18pt;
  border-radius: 4pt;
  overflow: hidden;
  height: 32vh;
}
.cover .cover-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.article-section {
  margin: 0 0 18pt;
  page-break-inside: avoid;
  break-inside: avoid;
}
.article-section h2 {
  font-family: var(--font-heading), serif;
  color: var(--color-heading);
  font-size: 15.5pt;
  margin: 0 0 8pt;
  padding-bottom: 4pt;
  border-bottom: 1pt solid var(--color-accent);
}
.article-section p {
  margin: 0 0 9pt;
}
.article-section figure {
  margin: 12pt 0;
  page-break-inside: avoid;
  break-inside: avoid;
}
.article-section figure img {
  width: 100%;
  border-radius: 3pt;
  display: block;
}
.article-section figcaption {
  font-size: 9pt;
  color: var(--color-muted);
  margin-top: 5pt;
}
.pull-quotes {
  margin: 6pt 0 20pt;
}
.pull-quote {
  border-left: 3pt solid var(--color-accent);
  margin: 0 0 14pt;
  padding: 2pt 0 2pt 16pt;
  page-break-inside: avoid;
  break-inside: avoid;
}
.pull-quote p {
  font-family: var(--font-serif), serif;
  font-style: italic;
  font-size: 13pt;
  color: var(--color-heading);
  margin: 0;
}
.pull-quote cite {
  display: block;
  margin-top: 5pt;
  font-size: 9.5pt;
  font-style: normal;
  color: var(--color-muted);
}
.sources {
  margin-top: 22pt;
  border-top: 1pt solid var(--color-muted);
  padding-top: 12pt;
}
.sources h2 {
  font-family: var(--font-heading), serif;
  font-size: 12pt;
  margin: 0 0 8pt;
}
.sources ol {
  margin: 0;
  padding-left: 16pt;
  font-size: 9pt;
  color: var(--color-muted);
}
.sources li {
  margin-bottom: 4pt;
}
.sources a {
  color: var(--color-primary);
}
.footer {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  gap: 14pt;
  align-items: flex-end;
  justify-content: space-between;
  padding: 8pt 34pt;
  font-size: 7.5pt;
  color: var(--color-muted);
  border-top: 0.5pt solid var(--color-muted);
  background: var(--color-page);
}
.footer .footer-brand {
  font-weight: 700;
}
.footer .footer-disclaimer {
  flex: 1;
  text-align: right;
}
